/**
 * AI-generated expression sheets for a custom character.
 *
 * Mina's engine swaps whole pictures of the same head (16 gaze directions, a near gaze ring, 4 blink
 * steps and ~36 reactions). Here every one of those pictures is generated by Gemini as an edit of the
 * master head, sliced out of 2x2 sprite sheets, background-keyed, registered to the master head and
 * blended onto it (so hair and outline never change), under exactly the names the WebGL engine
 * in index.html asks for.
 */
import { loadImage, sliceAndAlignGrid } from './faceIsolation';

export interface SheetCell {
  name: string;
  prompt: string;
}

export interface Sheet {
  id: string;
  label: string;
  cells: SheetCell[];
}

