// Engine ring order: the names must match what index.html asks for (nw has no near_ twin in the engine's naming, but is harmless)
const RING: [string, string][] = [
  ['right', 'to the RIGHT'],
  ['ene', 'to the RIGHT and slightly UP'],
  ['upright', 'UP and to the RIGHT'],
  ['nne', 'UP and slightly to the RIGHT'],
  ['up', 'straight UP'],
  ['nnw', 'UP and slightly to the LEFT'],
  ['nw', 'UP and to the LEFT'],
  ['wnw', 'to the LEFT and slightly UP'],
  ['left', 'to the LEFT'],
  ['wsw', 'to the LEFT and slightly DOWN'],
  ['downleft', 'DOWN and to the LEFT'],
  ['ssw', 'DOWN and slightly to the LEFT'],
  ['down', 'straight DOWN'],
  ['sse', 'DOWN and slightly to the RIGHT'],
  ['downright', 'DOWN and to the RIGHT'],
  ['ese', 'to the RIGHT and slightly DOWN'],
];

const gaze = (name: string, where: string, amount: string): SheetCell => ({
  name,
  prompt: `only the irises/pupils move: both eyes looking ${where} (viewer's point of view), shifted about ${amount} of the way to the corner of the eye; eyes fully open, brows and mouth exactly as the master`,
});

const FRAMES: SheetCell[] = [
  // far ring: clearly looking that way
  ...RING.map(([n, w]) => gaze(n, w, '85%')),
  // near ring: a small glance, so the eyes glide from rest to the far frame instead of snapping
  ...RING.map(([n, w]) => gaze(`near_${n}`, w, '40%')),
  { name: 'closed', prompt: 'both eyes fully CLOSED in a calm relaxed blink, neutral mouth as the master' },
  { name: 'half', prompt: 'eyelids HALF closed (mid-blink), looking straight at the camera, neutral mouth as the master' },
  { name: 'blink25', prompt: 'eyelids just starting to close: upper lids covering about 25% of the eyes, looking straight ahead, neutral mouth' },
  { name: 'blink75', prompt: 'eyelids almost closed: upper lids covering about 75% of the eyes, only a thin slit of the eyes visible, neutral mouth' },
  ...REACTIONS,
];

// 2x2 sheets give every frame a ~1000px cell (a 3x3 sheet leaves ~680px, visibly softer than the master head)
const CELLS_PER_SHEET = 4;

export const SHEETS: Sheet[] = Array.from({ length: Math.ceil(FRAMES.length / CELLS_PER_SHEET) }, (_, i) => {
  const cells = FRAMES.slice(i * CELLS_PER_SHEET, (i + 1) * CELLS_PER_SHEET);
  return { id: `sheet-${i + 1}`, label: `frames ${cells.map((c) => c.name).join('/')}`, cells };
});

export interface AiSheetResult {
  frames: Record<string, string>;
  failedSheets: string[];
  lastError?: string;
}

export type ImageProvider = 'gemini' | 'openai';

/** Which image backend to use, with the user's key and (for OpenAI) the chosen model ID. */
export interface ImageProviderConfig {
  provider: ImageProvider;
  apiKey: string;
  model?: string;
}

export const PROVIDER_NAMES: Record<ImageProvider, string> = { gemini: 'Gemini', openai: 'OpenAI' };

/** Error from the image API; `fatal` means retrying cannot help (bad key, billing, unavailable model...). */
export class ImageApiError extends Error {
  fatal: boolean;
  constructor(message: string, fatal = false) {
    super(message);
    this.name = 'ImageApiError';
    this.fatal = fatal;
  }
}

/** POSTs to the server's image endpoint and returns the generated image data URL. */
export async function requestImage(
  cfg: ImageProviderConfig,
  payload: Record<string, unknown>,
  failureLabel: string
): Promise<string> {
  const res = await fetch('/api/generate-expression', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...payload, provider: cfg.provider, apiKey: cfg.apiKey, model: cfg.model }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.success || !data.imageUrl) {
    throw new ImageApiError(data.error || `Failed to generate ${failureLabel}`, Boolean(data.fatal));
  }
  return data.imageUrl as string;
}

function requestSheet(params: {
  provider: ImageProviderConfig;
  references: string[];
  sheet: Sheet;
  style: 'pixar' | 'realistic';
  skinColorDescription?: string;
}): Promise<string> {
  return requestImage(
    params.provider,
    {
      referenceImages: params.references,
      expression: 'grid',
      cells: params.sheet.cells.map((c) => c.prompt),
      style: params.style,
      skinColorDescription: params.skinColorDescription,
    },
    `the ${params.sheet.label} sheet`
  );
}

/** The master head flattened on chroma-key green, exactly as the model should draw every cell. */
async function flattenOnGreen(transparentUrl: string, size = 768): Promise<string> {
  const img = await loadImage(transparentUrl);
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  const ctx = c.getContext('2d')!;
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, size, size);
  ctx.drawImage(img, 0, 0, size, size);
  return c.toDataURL('image/jpeg', 0.92);
}

/**
 * Generates every gaze / blink / reaction frame with Gemini and registers it to the master head.
 * Sheets that fail are reported in `failedSheets` so the caller can fall back for just those frames.
 */
export async function generateAiExpressionSheets(params: {
  provider: ImageProviderConfig;
  masterRestUrl: string;
  style: 'pixar' | 'realistic';
  skinColorDescription?: string;
  frameSize?: number;
  onProgress?: (done: number, total: number, label: string) => void;
}): Promise<AiSheetResult> {
  const { provider, masterRestUrl, style, skinColorDescription, onProgress } = params;
  const frameSize = params.frameSize ?? 1024;

  const masterImg = await loadImage(masterRestUrl);
  const masterCanvas = document.createElement('canvas');
  masterCanvas.width = masterImg.naturalWidth || masterImg.width;
  masterCanvas.height = masterImg.naturalHeight || masterImg.height;
  masterCanvas.getContext('2d', { willReadFrequently: true })!.drawImage(masterImg, 0, 0);

  // Only the master head is sent: every frame is an edit of it, so the photo cannot pull frames off-model
  const references = [await flattenOnGreen(masterRestUrl, 1024)];

  const frames: Record<string, string> = {};
  const failedSheets: string[] = [];
  let lastError: string | undefined;
  let fatal = false;
  let done = 0;

  const runSheet = async (sheet: Sheet) => {
    // A sheet can come back unusable (wrong layout, refusal, transient quota): try up to three times
    for (let attempt = 0; attempt < 3 && !fatal; attempt++) {
      if (attempt > 0) await new Promise((r) => setTimeout(r, 3000 * attempt));
      try {
        const sheetUrl = await requestSheet({ provider, references, sheet, style, skinColorDescription });
        const aligned = await sliceAndAlignGrid(
          sheetUrl,
          masterCanvas,
          sheet.cells.map((c) => c.name),
          2,
          frameSize
        );
        // Accept the sheet only when most of its cells could be extracted
        if (Object.keys(aligned).length >= Math.ceil(sheet.cells.length * 0.7)) {
          Object.assign(frames, aligned);
          return;
        }
        lastError = `The ${sheet.label} sheet did not contain a usable head in every cell.`;
      } catch (err: any) {
        lastError = err?.message || String(err);
        // A rejected key, exhausted billing or a missing model will not get better by retrying 18 sheets
        if ((err instanceof ImageApiError && err.fatal) || /api key|API_KEY_INVALID|PERMISSION_DENIED|unauthori[sz]ed/i.test(lastError || '')) {
          fatal = true;
        }
      }
    }
    failedSheets.push(sheet.id);
  };

  // A small pool keeps total time reasonable without hammering the per-minute quota (OpenAI sheets are slower and rate-limited harder)
  const queue = [...SHEETS];
  const workers = Array.from({ length: provider.provider === 'openai' ? 3 : 4 }, async () => {
    while (queue.length && !fatal) {
      const sheet = queue.shift()!;
      await runSheet(sheet);
      done++;
      onProgress?.(done, SHEETS.length, sheet.label);
    }
  });
  await Promise.all(workers);
  if (fatal) failedSheets.push(...queue.map((s) => s.id));

  return { frames, failedSheets, lastError };
}
